<script setup lang="ts">
import {computed,onMounted,ref} from 'vue'
import {useRoute,useRouter} from 'vue-router'
import {usePhasePage} from '../phasePage'
import {localInput,localToInstant,validateCorrection} from '../time'
import type {AttendanceDetail} from '../types'
import {punchBreaks,reviewText} from '../attendanceReview'
import PhaseStatus from '../components/PhaseStatus.vue'
const route=useRoute(),router=useRouter(),scheduleId=String(route.query.schedule||''),id=crypto.randomUUID(),{api,home,t,p,base,loading,busy,failure,load,write,english}=usePhasePage(),data=ref<AttendanceDetail|null>(null),inAt=ref(''),outAt=ref(''),breaks=ref<{start:string;end:string;ruleId?:string|null;legacy?:boolean}[]>([]),overrideBreak=ref(false),reason=ref('')
const breakRules=computed(()=>punchBreaks(data.value?.attendance.schedule.shift)),hasRules=computed(()=>!!data.value?.attendance.schedule.shift.rules),r=(key:Parameters<typeof reviewText>[0])=>reviewText(key,english())
onMounted(()=>{if(!scheduleId){failure.value=p('invalid');return}void load(()=>api().get<AttendanceDetail>('/attendance/'+scheduleId),v=>{data.value=v;const a=v.attendance,z=a.schedule.timezone;inAt.value=localInput(a.session?.inAt||a.schedule.startAt,z);outAt.value=localInput(a.session?.outAt||a.schedule.endAt,z);breaks.value=(a.session?.breaks||[]).map(b=>({start:localInput(b.start,z),end:localInput(b.end,z),ruleId:b.ruleId,legacy:!b.ruleId}));overrideBreak.value=a.session?.overrideBreak||!!a.schedule.shift.rules||a.schedule.shift.breakMode==='manual'})})
function save(){if(!data.value)return;try{const a=data.value.attendance,z=a.schedule.timezone;const body={scheduleId,basedSessionVersion:a.session?.version||0,inAt:localToInstant(inAt.value,z),outAt:localToInstant(outAt.value,z),breaks:(overrideBreak.value||a.schedule.shift.rules||a.schedule.shift.breakMode==='manual'?breaks.value:[]).map(b=>({start:localToInstant(b.start,z),end:localToInstant(b.end,z),...(b.ruleId?{ruleId:b.ruleId}:{})})),overrideBreak:overrideBreak.value,reason:reason.value.trim()};if(hasRules.value&&breaks.value.some(b=>!b.legacy&&!breakRules.value.some(rule=>rule.id===b.ruleId)))throw new Error();if(!validateCorrection(body,new Date().toISOString())||Date.parse(body.inAt)<Date.parse(a.schedule.startAt)-12*3600000||Date.parse(body.outAt)>Date.parse(a.schedule.endAt)+12*3600000)throw new Error();void write(()=>api().put('/corrections/'+id,body),()=>router.push(base.value+'/corrections/'+id+'?schedule='+scheduleId).then(()=>{}))}catch{failure.value=p('timeInvalid')}}
</script>
<template><section class="wf-panel wf-form-panel"><h2>{{p('newCorrection')}}</h2><PhaseStatus :failure="failure" :loading="loading"/><template v-if="data&&!loading"><p class="wf-hint">{{data.attendance.schedule.employeeName}} · {{data.attendance.schedule.workDate}} · {{p('timezone')}}: {{data.attendance.schedule.timezone}}</p><p v-if="home?.myself?.id!==data.attendance.schedule.employeeId||data.attendance.schedule.status==='cancelled'" role="alert">{{t('noAccess')}}</p><p v-else-if="data.corrections.some(c=>c.status==='pending')" role="alert">{{p('pendingConflict')}}</p><form v-else @submit.prevent="save"><fieldset :disabled="busy"><p class="wf-hint">{{p('correctionHint')}}</p><div class="wf-grid"><label>{{p('inAt')}}<input v-model="inAt" type="datetime-local" required></label><label>{{p('outAt')}}<input v-model="outAt" type="datetime-local" required></label></div><label class="wf-check"><input v-model="overrideBreak" type="checkbox" :disabled="hasRules||data.attendance.schedule.shift.breakMode==='manual'">{{p('overrideBreak')}}</label><p v-if="!overrideBreak&&data.attendance.schedule.shift.breakMode==='duration'" class="wf-hint">{{p('durationHint')}}</p><template v-if="hasRules||overrideBreak||data.attendance.schedule.shift.breakMode==='manual'"><legend>{{p('breaks')}}</legend><div v-for="(b,index) in breaks" :key="index" class="wf-break-row"><label v-if="hasRules&&breakRules.length">{{r('selectBreak')}}<select v-model="b.ruleId" :required="!b.legacy"><option v-if="b.legacy" :value="undefined">{{r('legacyBreak')}}</option><option v-for="rule in breakRules" :key="rule.id" :value="rule.id">{{rule.name}}</option></select></label><label>{{p('startTime')}}<input v-model="b.start" type="datetime-local" required></label><label>{{p('endTime')}}<input v-model="b.end" type="datetime-local" required></label><button type="button" @click="breaks.splice(index,1)">{{p('remove')}}</button></div><button type="button"  :disabled="breaks.length>=20||(hasRules&&!breakRules.length)" @click="breaks.push({start:'',end:'',ruleId:breakRules.length===1?breakRules[0]!.id:undefined})">{{p('addBreak')}}</button></template><label class="wf-section">{{p('reason')}}<textarea v-model="reason" required maxlength="500" rows="3"></textarea></label></fieldset><footer class="wf-form-actions"><RouterLink class="wf-button" :to="base+'/attendance/'+scheduleId">{{t('cancel')}}</RouterLink><button class="primary" :disabled="busy">{{t(busy?'saving':'save')}}</button></footer></form></template></section></template>
